-- BACKLOG-3473 MUTANT (generated by generate.mjs from the shipped files; do not hand-edit)
-- the helper treats an override with no `enabled` key as OFF (the read functions treat it as ON)
-- targets: c25a
-- Runs INSIDE a control's transaction, after the prelude; rolled back with it.

CREATE OR REPLACE FUNCTION public._override_above_tier(
  p_feature_key text,
  p_min_tier    text,
  p_plan_tier   text,
  p_override    jsonb
)
RETURNS boolean
LANGUAGE sql
IMMUTABLE
SET search_path = public
AS $$
  SELECT COALESCE((p_override ->> 'enabled')::boolean, false)
     AND p_min_tier IS NOT NULL
     AND public.tier_rank(p_plan_tier) < public.tier_rank(p_min_tier)
$$;

DO $proof$
BEGIN
  IF NOT (pg_get_functiondef('public._override_above_tier(text,text,text,jsonb)'::regprocedure) LIKE '%''enabled'')::boolean, false)%') THEN
    RAISE EXCEPTION 'MUTATION NOT APPLIED';
  END IF;
END
$proof$;
SELECT 'MUTATION APPLIED: ' || ('missing enabled counts as OFF') AS mutation;
